try{Object.assign(libraryPrefs,JSON.parse(localStorage.getItem('audit-library-preferences')||'{}'));folderMeta=JSON.parse(localStorage.getItem('audit-folder-metadata')||'{}');Object.assign(storageQuota,JSON.parse(localStorage.getItem('audit-storage-quota')||'{}'));}catch{}
// The file list uses fixed business columns; saved column preferences no longer apply.
