if(!localStorage.getItem('audit-library-width-v2')){if(libraryPrefs.folderWidth===202)libraryPrefs.folderWidth=240;try{localStorage.setItem('audit-library-width-v2','1');}catch{}}
const libraryFilters={status:'',type:''};
let librarySort='uploaded-desc',libraryReturn=null;
