const libIcon=(name,action,label,attrs='')=>'<button class="iconbtn" data-action="'+action+'" title="'+E(label)+'" aria-label="'+E(label)+'" '+attrs+'>'+I(name,'icon-sm')+'</button>';
const libAttrs=d=>'data-id="'+E(d.id)+'"';
const libMeta=(space,path)=>folderMeta[directoryKey(space,path)]||{};
function libInherited(space,path){let p=folderPath(path);for(;;){const m=libMeta(space,p);if(m.permission||m.reference||m.source==='OSS')return m;if(!p)break;p=p.split('/').slice(0,-1).join('/');}return{};}
function libWritable(space=state.space,path=state.folder){const m=libInherited(space,path);return !m.reference&&m.source!=='OSS'&&m.permission!=='READ'&&m.permission!=='NONE'&&(space!=='公共空间'||state.libraryAdmin===true||m.permission==='FULL');}
const libReadable=(space,path)=>typeof auditFolderAccess==='function'?auditFolderAccess(space,path).read:libInherited(space,path).permission!=='NONE';
const libCanParse=d=>{if(!d)return false;const r=state.uploads.find(u=>u.id===d.id),status=r?.contentStatus||d.content_status||r?.status;if(['uploading','processing','正在上传','正在解析'].includes(status))return false;return typeof auditFileAccess==='function'?auditFileAccess(d).parse:libCanEdit(d)||(state.libraryAdmin===true&&d.source==='OSS');};
const libCanEdit=d=>typeof auditFileAccess==='function'?['rename','delete','move','attachments'].some(k=>auditFileAccess(d)[k]):!!d&&!d.deleted&&libWritable(d.space,d.folder)&&!d.refSourceId;
const libStatus=d=>{const record=state.uploads.find(u=>u.id===d.id),status=record?.contentStatus||d.content_status||record?.status;if(d.parseError||['failed','解析失败'].includes(status))return '解析失败';if(!d.importedOnly&&['processing','正在解析'].includes(status))return '解析中';return d.local||d.importedOnly||['pending','uploading','stuck','未解析','正在上传','已停止'].includes(status)?'未解析':'解析完成';};
const libStatusTag=d=>{const status=libStatus(d);return tag(status,status==='解析失败'?'red':status==='解析完成'?'green':'amber');};
const libSize=d=>{const m=String(d.size||'').match(/([\d.]+)\s*(B|KB|MB|GB)/i);return d.byteSize??(m?+m[1]*({B:1,KB:1024,MB:1048576,GB:1073741824}[m[2].toUpperCase()]):0);};
const libFormat=n=>n>=1073741824?(n/1073741824).toFixed(2)+' GB':n>=1048576?(n/1048576).toFixed(1)+' MB':(n/1024).toFixed(1)+' KB';
const libSelected=()=>selectedDocs(state.librarySelected).filter(d=>!d.deleted);
const libReady=d=>!d.local&&!d.parseError&&!d.importedOnly&&!d.deleted&&libStatus(d)==='解析完成';
const libCount=docs=>({ready:docs.filter(libReady).length,failed:docs.filter(d=>d.parseError).length,pending:docs.filter(d=>(d.local||d.importedOnly)&&!d.parseError).length,missing:docs.filter(d=>d.importedOnly).length});
function libSummary(docs){const c=libCount(docs);return '完成 '+c.ready+(c.pending?' · 待解析 '+c.pending:'')+(c.failed?' · 失败 '+c.failed:'');}
persist=function(){libraryBase.persist();try{localStorage.setItem('audit-library-preferences',JSON.stringify(libraryPrefs));localStorage.setItem('audit-folder-metadata',JSON.stringify(folderMeta));localStorage.setItem('audit-storage-quota',JSON.stringify(storageQuota));}catch{}};
function libMatches(d){if(!libReadable(d.space,d.folder))return false;const type=d.name.split('.').at(-1).toLowerCase(),f=libraryFilters;return (!f.status||libStatus(d)===f.status)&&(!f.type||(f.type==='image'?['png','jpg','jpeg','gif','webp','bmp','svg'].includes(type):f.type==='other'?!['pdf','doc','docx','xls','xlsx','ppt','pptx','csv','png','jpg','jpeg','gif','webp','bmp','svg'].includes(type):type===f.type));}
function libItems(){const active=!!(state.query||libraryFilters.status||libraryFilters.type),folders=!active&&!state.libraryRecursive?childDirectories(state.space,state.folder).map(path=>({kind:'folder',path})):[];const docs=inDirectory(state.space,state.folder,!!state.libraryRecursive,state.query).filter(libMatches);docs.sort((a,b)=>{if(librarySort==='name')return a.name.localeCompare(b.name,'zh-CN');if(librarySort==='size-desc')return libSize(b)-libSize(a);const key=librarySort==='viewed-desc'?'lastViewed':librarySort.startsWith('uploaded')?'uploadedAt':'date',cmp=String(b[key]||b.date||'').localeCompare(String(a[key]||a.date||''));return librarySort==='uploaded-asc'?-cmp:cmp;});return [...folders,...docs.map(file=>({kind:'file',file}))];}
function libTree(path='',depth=0){const q=folderQueries.library.toLowerCase();return childDirectories(state.space,path).filter(p=>!q||directoryPaths(state.space).some(x=>underFolder(x,p)&&x.toLowerCase().includes(q))).map(p=>{const k='library::'+directoryKey(state.space,p),has=childDirectories(state.space,p).length>0,closed=!q&&treeClosed.has(k),m=libInherited(state.space,p);return '<div class="dir-nav-line '+(folderPath(state.folder)===p?'selected':'')+'" style="--depth:'+depth+'">'+(has?'<button class="tree-chevron" data-action="v3-toggle-dir" data-key="'+E(k)+'" aria-expanded="'+!closed+'" aria-label="展开或收起 '+E(folderName(p))+'">'+I(closed?'chevron':'down','icon-sm')+'</button>':'<span class="tree-chevron"></span>')+'<button class="dir-nav-name" data-action="folder" '+(!libReadable(state.space,p)?'disabled':'')+' data-id="'+E(p)+'" title="'+E(p)+(m.reference?' · 引用目录':!libWritable(state.space,p)?' · 只读':'')+'">'+I(m.reference?'link':'folder','icon-sm')+'<span>'+E(folderName(p))+'</span>'+(!libWritable(state.space,p)?I('lock','icon-sm'):'')+'</button>'+libIcon('more','lib-folder-menu','管理 '+folderName(p),'data-path="'+E(p)+'"')+'</div>'+(!closed?libTree(p,depth+1):'');}).join('');}
function libFilterMenu(){const active=libraryFilters.status||libraryFilters.type;return '<details class="lib-dropdown"><summary class="btn sm '+(active?'soft':'')+'">'+I('filter','icon-sm')+'筛选'+(active?' · 已启用':'')+I('down','icon-sm')+'</summary><div class="lib-menu lib-filter"><label>文档状态<select aria-label="按文档状态筛选" data-lib-change="status">'+options(['全部状态','解析完成','未解析','解析中','解析失败'],libraryFilters.status||'全部状态')+'</select></label><label>文件类型<select aria-label="按文件类型筛选" data-lib-change="type">'+[['','全部类型'],...['pdf','doc','docx','xls','xlsx','ppt','pptx','csv'].map(x=>[x,x.toUpperCase()]),['image','图片'],['other','其他']].map(([v,n])=>'<option value="'+v+'" '+(libraryFilters.type===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>'+A('重置筛选','lib-reset')+'</div></details>';}
function libFileRow(d){const attrs=libAttrs(d),writable=libCanEdit(d);return '<tr data-file-id="'+E(d.id)+'" class="'+(state.librarySelected.includes(d.id)?'is-selected':'')+'"><td><input type="checkbox" data-lib-change="check" '+attrs+' aria-label="选择 '+E(d.name)+'" '+(state.librarySelected.includes(d.id)?'checked':'')+'></td><td><div class="row">'+ficon(d)+'<div class="lib-file-name"><button class="filename" data-action="source" '+attrs+' title="'+E(d.name)+'">'+E(d.name)+'</button><div class="file-sub" title="'+E(d.space+' / '+(folderPath(d.folder)||'根目录'))+'">'+E(state.libraryRecursive?folderPath(d.folder)||'空间根目录':d.size||'—')+(d.refSourceId?' · 引用资料':'')+(d.attachments?.length?' · '+d.attachments.length+' 个附件':'')+'<span class="lib-mobile-status">'+libStatusTag(d)+'</span></div></div></div></td><td title="'+E(d.parseError||libStatus(d))+'">'+libStatusTag(d)+'</td>'+libraryPrefs.columns.map(c=>'<td class="lib-meta">'+E(c==='owner'?d.owner||'当前用户':c==='uploaded'?(d.uploadedAt||d.date||'—').slice(0,10):c==='viewed'?(d.lastViewed?.replace('T',' ').slice(0,16)||'—'):c==='size'?d.size:d.space+' / '+(folderPath(d.folder)||'根目录'))+'</td>').join('')+'<td class="lib-row-actions"><div class="row gap6">'+libIcon('download','lib-download','下载 '+d.name,attrs)+libIcon('edit','lib-rename-file','重命名 '+d.name,attrs+(writable?'':' disabled'))+libIcon('paperclip','lib-attachments','附件 '+d.name,attrs)+libIcon('more','file-detail','更多操作 '+d.name,attrs)+'</div></td></tr>';}
function libTable(items){const files=items.filter(i=>i.kind==='file').map(i=>i.file),all=files.length&&files.every(d=>state.librarySelected.includes(d.id)),colNames={owner:'所有者',uploaded:'上传时间',viewed:'最近查看',size:'大小',location:'位置'};return '<div class="lib-table-scroll"><table class="table lib-table"><thead><tr><th class="lib-check"><input type="checkbox" aria-label="选择本页文件，不含文件夹" data-lib-change="page" '+(all?'checked':'')+' '+(!files.length?'disabled':'')+'></th><th class="lib-name">名称</th><th class="lib-status">文档状态</th>'+libraryPrefs.columns.map(c=>'<th class="lib-col-'+c+'">'+colNames[c]+'</th>').join('')+'<th class="lib-actions">操作</th></tr></thead><tbody>'+items.map(item=>{if(item.kind==='file')return libFileRow(item.file);const count=inDirectory(state.space,item.path,true).length,m=libInherited(state.space,item.path);return '<tr class="folder-entry" data-folder-path="'+E(item.path)+'"><td></td><td><div class="row">'+I(m.reference?'link':'folder','folder-symbol')+'<div class="lib-file-name"><button class="filename" data-action="folder" data-id="'+E(item.path)+'">'+E(folderName(item.path))+'</button><div class="file-sub">'+count+' 份资料 · 含子文件夹'+(m.reference?' · 引用目录':'')+'</div></div></div></td><td>'+tag(!libWritable(state.space,item.path)?'只读文件夹':'文件夹')+'</td>'+libraryPrefs.columns.map(()=>'<td class="lib-meta">—</td>').join('')+'<td class="lib-row-actions"><div class="row">'+A('打开','folder','data-id="'+E(item.path)+'"')+libIcon('more','lib-folder-menu','管理 '+folderName(item.path),'data-path="'+E(item.path)+'"')+'</div></td></tr>';}).join('')+'</tbody></table></div>';}
library=function(){const items=libItems(),size=libraryPrefs.pageSize,pages=Math.max(1,Math.ceil(items.length/size));state.page=Math.max(1,Math.min(state.page,pages));const shown=pageItems(items,state.page,size),selected=libSelected(),scopeDocs=state.docs.filter(d=>!d.deleted&&!d.refSourceId&&d.space===state.space),used=scopeDocs.reduce((n,d)=>n+libSize(d),0),limit=(storageQuota.personal||4)*1073741824,writable=libWritable(),meta=libInherited(state.space,state.folder);return '<div class="page library-v5"><div class="lib-commandbar"><div class="row"><h1>资料管理</h1><span class="lib-total">'+scopeDocs.length+' 份资料</span></div><div class="row lib-top-actions">'+B(I('tasks','icon-sm')+'任务中心','nav-tasks','sm')+B(I('uploadHistory','icon-sm')+'上传记录','upload-records','sm')+B(I('upload','icon-sm')+'上传资料','upload','primary sm',writable?'':'disabled')+'</div></div><div class="lib-workspace '+(!libraryPrefs.showFolders?'folders-hidden ':'')+(!libraryPrefs.showTools?'tools-hidden ':'')+(libraryPrefs.mobileFolderOpen?'mobile-folder-open':'')+'"><section class="lib-browser card" style="--library-folder-width:'+Math.min(320,Math.max(135,libraryPrefs.folderWidth||202))+'px"><aside class="lib-folders" aria-label="资料目录"><div class="lib-folder-head"><select aria-label="切换资料空间" data-lib-change="space">'+options(SPACE_ORDER,state.space)+'</select><div class="row">'+libIcon('refresh','lib-refresh','刷新目录')+libIcon('focusPath','lib-tree-mode',libraryPrefs.focused?'显示完整目录':'聚焦当前目录')+'<span class="lib-mobile-only">'+libIcon('close','lib-toggle-folders','关闭资料目录')+'</span></div></div><div class="lib-folder-search"><input id="library-folder-search" class="tree-search" aria-label="搜索资料文件夹" placeholder="查找文件夹" data-v3-input="folder-search" data-context="library" value="'+E(folderQueries.library)+'"></div><div class="lib-tree-scroll"><div class="dir-nav-line '+(!folderPath(state.folder)?'selected':'')+'"><button class="dir-nav-name" data-action="folder" data-id="全部资料">'+I('folder','icon-sm')+'<span>空间根目录</span></button>'+libIcon('more','lib-folder-menu','管理空间根目录','data-path=""')+'</div>'+libTree()+'</div><div class="lib-storage"><div class="row between"><span>'+E(state.space)+'</span>'+A('空间用量','lib-storage')+'</div><div class="bar"><i style="width:'+Math.min(100,used/limit*100)+'%"></i></div><div class="row between"><span>'+libFormat(used)+(state.space==='个人空间'?' / '+storageQuota.personal+' GB':'')+'</span>'+A('上传记录','upload-records')+'</div></div></aside><div class="lib-folder-resizer" role="separator" aria-label="调整资料目录宽度" aria-orientation="vertical" tabindex="0"></div><div class="lib-files"><div class="lib-path-row"><div class="row">'+libIcon('folderTree','lib-toggle-folders',libraryPrefs.showFolders?'收起资料目录':'展开资料目录')+folderCrumbs(state.space,state.folder,'library')+'</div><div class="row">'+(!writable?tag(meta.reference?'引用目录 · 只读':'只读','amber'):'')+libIcon('toolbox','lib-toggle-tools',libraryPrefs.showTools?'收起分析工具':'展开分析工具')+'</div></div><div class="lib-toolbar"><div class="search">'+I('search')+'<input id="lib-file-query" aria-label="搜索资料名称" placeholder="搜索文件" value="'+E(state.query)+'" data-lib-input="query"></div><select aria-label="资料搜索范围" data-lib-change="scope"><option value="direct" '+(!state.libraryRecursive?'selected':'')+'>仅本级</option><option value="recursive" '+(state.libraryRecursive?'selected':'')+'>含子文件夹</option></select>'+libFilterMenu()+'<details class="lib-dropdown"><summary class="btn sm">更多'+I('down','icon-sm')+'</summary><div class="lib-menu">'+B('文本检索','lib-search','ghost sm')+B('移动所选文件','lib-move-selected','ghost sm',selected.length?'':'disabled')+B('重新解析','lib-reparse','ghost sm',selected.some(d=>d.local||d.parseError)?'':'disabled')+B('批量删除','lib-delete-selected','ghost sm',selected.length?'':'disabled')+'</div></details></div><div class="lib-selection"><div class="row">'+(selected.length?A('已选 '+selected.length+' 份','library-selected')+'<span class="lib-selection-detail">'+libSummary(selected)+'</span>'+A('清空','library-clear'):'<span class="muted">勾选资料，使用右侧工具开始分析</span>')+'</div><select aria-label="文件排序" data-lib-change="sort">'+[['uploaded-desc','上传时间 ↓'],['uploaded-asc','上传时间 ↑'],['name','名称 A—Z'],['viewed-desc','最近查看 ↓'],['size-desc','文件大小 ↓']].map(([v,n])=>'<option value="'+v+'" '+(librarySort===v?'selected':'')+'>'+n+'</option>').join('')+'</select></div>'+libTable(shown)+(!items.length?'<div class="lib-empty">'+I('folder')+'<h3>'+(state.query||libraryFilters.status||libraryFilters.type?'没有符合条件的资料':'此文件夹暂无资料')+'</h3><p>'+(state.query||libraryFilters.status||libraryFilters.type?'调整筛选条件，已选资料仍保留。':'上传文件或文件夹，保留资料的原有层级。')+'</p>'+B(state.query||libraryFilters.status||libraryFilters.type?'清除筛选':'上传资料',state.query||libraryFilters.status||libraryFilters.type?'lib-reset':'upload','soft sm',writable||state.query||libraryFilters.status||libraryFilters.type?'':'disabled')+'</div>':'')+'<div class="lib-pagination"><span>共 '+items.length+' 项'+(items.some(x=>x.kind==='folder')?' · 文件夹与文件':'')+'</span><div class="row"><select aria-label="每页显示数量" data-lib-change="size">'+[10,20,50,100].map(n=>'<option '+(n===size?'selected':'')+' value="'+n+'">'+n+' 项/页</option>').join('')+'</select>'+B(I('back','icon-sm'),'lib-prev','sm',state.page===1?'disabled aria-label="上一页"':'aria-label="上一页"')+'<span>'+state.page+' / '+pages+'</span>'+B(I('chevron','icon-sm'),'lib-next','sm',state.page===pages?'disabled aria-label="下一页"':'aria-label="下一页"')+'</div></div></div></section><aside class="lib-tools card"><div class="lib-tools-head"><h3>分析工具</h3>'+libIcon('close','lib-toggle-tools','收起分析工具')+'</div><button class="lib-scope-summary" data-action="library-selected"><b>'+(selected.length?'已选 '+selected.length+' 份资料':'先选资料，再选工具')+'</b><span>'+(selected.length?libSummary(selected):'也可进入工具后添加资料')+'</span></button>'+['基础分析','审计专题','数据核对'].map(g=>'<div class="tool-group-title">'+g+'</div>'+TOOLS.filter(t=>t.group===g).map(t=>'<button class="lib-tool" data-action="open-tool" data-id="'+t.id+'" title="'+E(t.desc)+'"><span class="tool-symbol" style="--tool-color:'+toolColor[t.id]+'">'+I(t.icon)+'</span><span>'+E(t.name)+'</span>'+I('chevron','icon-sm')+'</button>').join('')).join('')+'</aside></div></div>';};

// Binary source files are kept in browser storage for genuine downloads and retry after refresh.
let libDbPromise;
function libDb(){return libDbPromise??=new Promise((resolve,reject)=>{const req=indexedDB.open('audit-document-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function libStoreFile(id,f){try{const db=await libDb();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(f,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch{toast('原文件未能保存到浏览器，请保留本地文件以便再次读取。');}}
async function libGetFile(id){if(uploadSources.has(id))return uploadSources.get(id);try{const db=await libDb();return await new Promise(resolve=>{const req=db.transaction('files').objectStore('files').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);});}catch{return null;}}
async function libDownload(d){const source=await libGetFile(d.refSourceId||d.id);if(source){const url=URL.createObjectURL(source),a=document.createElement('a');a.href=url;a.download=d.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(d.rows&&d.columns){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([d.columns,...d.rows]),'资料明细');XLSX.writeFile(wb,d.name.replace(/\.[^.]+$/,'')+'.xlsx');return;}if(d.text){openModal('lib-download-text',{id:d.id});return;}toast('未找到原始文件，请先补充原文。');}
function libUploadCommit(files,overwrite=[]){if(!libWritable())return toast('目标目录只读，无法上传。');const used=state.docs.filter(d=>!d.deleted&&!d.refSourceId&&d.space==='个人空间'&&!overwrite.includes(d.id)).reduce((n,d)=>n+libSize(d),0);if(state.space==='个人空间'&&used+files.reduce((n,f)=>n+f.size,0)>storageQuota.personal*1073741824)return toast('个人空间额度不足，请整理资料或联系文件管理员。');const oldIds=new Set(state.docs.map(d=>d.id));overwrite.forEach(id=>{const d=file(id);if(d)d.deleted=true;state.librarySelected=state.librarySelected.filter(x=>x!==id);});libraryBase.uploadFiles(files);state.docs.filter(d=>!oldIds.has(d.id)).forEach(d=>{const f=uploadSources.get(d.id);d.owner='当前用户';d.uploadedAt=new Date().toISOString();d.byteSize=f?.size||0;if(f)libStoreFile(d.id,f);});libPruneDrafts(overwrite);persist();}
function libUploadConflicts(files){const seen=new Set(),space=state.space,parent=folderPath(state.folder),entries=files.map((f,index)=>{const parts=(f.relativePath||f.webkitRelativePath||f.name).split('/'),path=typeof auditUploadTargetFolder==='function'?auditUploadTargetFolder(f,space,parent):[parent,...parts.slice(0,-1)].filter(Boolean).join('/'),key=path.toLowerCase()+'/'+f.name.toLowerCase(),old=state.docs.find(d=>!d.deleted&&d.space===space&&folderPath(d.folder).toLowerCase()===path.toLowerCase()&&d.name.toLowerCase()===f.name.toLowerCase()),duplicate=seen.has(key);seen.add(key);return{index,name:f.relativePath||f.webkitRelativePath||f.name,oldId:old?.id,duplicate,choice:old||duplicate?'skip':'new'};});if(entries.some(e=>e.oldId||e.duplicate)){openModal('lib-upload-conflicts',{files,entries});}else{openModal('upload',{items:[]});libUploadCommit(files);}}
uploadFiles=function(files){const arr=[...files];if(!arr.length)return;if(!libWritable()){toast('当前目录为只读，请选择可上传的目录。');return;}if(arr.some(f=>f.webkitRelativePath)){const types=[...new Set(arr.map(f=>f.name.split('.').at(-1).toLowerCase()))];openModal('lib-upload-types',{files:arr,types,selected:[...types]});}else libUploadConflicts(arr);};

function libForm(label,id,value='',extra=''){return '<label class="field"><span>'+label+'</span><input id="'+id+'" value="'+E(value)+'" '+extra+'></label>';}
function libError(message){const el=$('#lib-error');if(el)el.textContent=message;else toast(message);}
const libErrorHtml='<div id="lib-error" class="error" role="alert"></div>';
function libTargetOptions(space,exclude=''){return ['根目录',...directoryPaths(space)].filter(p=>libWritable(space,p)&&(!exclude||!underFolder(p,exclude))).map(p=>'<option value="'+E(folderPath(p))+'">'+E(p)+'</option>').join('');}
function libDeleteBody(docs){return '<p>将从资料管理中删除以下 '+docs.length+' 份资料，已有任务的历史引用会保留。</p><div class="lib-confirm-list">'+docs.map(d=>'<div>'+E(d.name)+(libCanEdit(d)?'':tag('只读，无法删除','amber'))+'</div>').join('')+'</div>'+libErrorHtml;}
function libPermissionRows(m){return simpleTable(['授权对象','权限','范围','操作'],(m.grants||[]).map((g,i)=>[E(g.name)+(g.type==='ORG'?'（机构）':'（用户）'),g.level==='MANAGE'?'管理'+(g.delegate?' · 可分权':''):'查看',g.descendants?'含下级机构':'当前对象',A('撤销','lib-revoke','data-index="'+i+'"')]),true);}
modalContent=function(){const d=modalData;
 if(modal==='library-selected')return modalFrame('已选资料 · '+libSelected().length+' 份','跨目录和空间保留；取消选择不会删除文件。','<div class="row between mb"><span>'+libSummary(libSelected())+'</span>'+A('清空已选','lib-clear-selection-modal')+'</div>'+libSelected().map(f=>'<div class="picked-item">'+ficon(f)+'<div class="grow"><button class="filename" data-action="source" '+libAttrs(f)+'>'+E(f.name)+'</button><small>'+E(f.space+' / '+(folderPath(f.folder)||'根目录'))+'</small></div>'+libStatusTag(f)+libIcon('close','unselect-library','取消选择 '+f.name,libAttrs(f))+'</div>').join(''),B('完成','close-modal','primary'),'medium');
 if(modal==='file-detail'){const f=file(d.id);if(!f)return libraryBase.modalContent();return modalFrame('资料详情',E(f.name),'<div class="lib-details">'+[['位置',f.space+' / '+(folderPath(f.folder)||'根目录')],['文档状态',libStatus(f)],['所有者',f.owner||'当前用户'],['大小',f.size||'—'],['上传时间',f.uploadedAt||f.date||'—'],['最近查看',f.lastViewed?.replace('T',' ').slice(0,19)||'尚未查看']].map(([a,b])=>'<div><span>'+a+'</span><b>'+E(b)+'</b></div>').join('')+'</div>'+(f.parseError?'<p class="error">'+E(f.parseError)+'</p>':'')+'<div class="row mt">'+B('查看原文','source','sm',libAttrs(f))+B('下载','lib-download','sm',libAttrs(f))+B('附件关联','lib-attachments','sm',libAttrs(f))+'</div>'+libErrorHtml,B('删除文件','lib-delete-file','danger sm',libAttrs(f)+(libCanEdit(f)?'':' disabled'))+B('移动','lib-move-file','sm',libAttrs(f)+(libCanEdit(f)?'':' disabled'))+B('重命名','lib-rename-file','sm',libAttrs(f)+(libCanEdit(f)?'':' disabled'))+B('关闭','close-modal'),'medium');}
 if(modal==='lib-attachments'){const f=file(d.id),can=libCanEdit(f);return modalFrame('附件管理',E(f.name)+' · '+(f.attachments?.length||0)+' 个附件',selectedDocs(f.attachments||[]).map(a=>'<div class="picked-item">'+ficon(a)+'<span class="grow">'+E(a.name)+'</span>'+A('查看原文','source',libAttrs(a))+(can?A('移除关联','lib-unlink','data-main="'+f.id+'" '+libAttrs(a)):'')+'</div>').join('')||'<div class="compact-empty">尚未关联附件。请根据正文约定核对资料是否齐全。</div>',B('关闭','close-modal')+(can?B('关联已有资料','lib-pick-attachment','primary',libAttrs(f)):tag('当前资料只读','amber')),'medium');}
 if(modal==='lib-name')return modalFrame(d.folder?'重命名文件夹':d.create?'新建文件夹':'重命名文件',E(d.space+' / '+(d.path||'根目录')),libForm('名称','lib-name',d.value,'maxlength="120" autocomplete="off"')+'<p class="hint">'+(d.folder?'下级目录与文件会一并保留，已有分析任务引用不变。':d.create?'同一层可以同时存放文件和文件夹。':'保留原文件类型和已有分析引用。')+'</p>'+libErrorHtml,B('取消','close-modal')+B('保存','lib-save-name','primary'),'small');
 if(modal==='lib-folder-menu'){const space=d.space,path=d.path,m=libInherited(space,path),own=libMeta(space,path),can=libWritable(space,path);return modalFrame(folderName(path),E(space+' / '+(path||'根目录')),(!can?'<p class="lib-readonly">'+(m.reference?'引用资料随源目录更新；取消引入不会删除源文件。':'当前目录只读，可浏览、下载和选入分析。')+'</p>':'')+'<div class="lib-folder-actions">'+B(I('plus')+'新建子文件夹','lib-create-at','',can&&!own.boundOrg?'':'disabled')+(path?B(I('edit')+'重命名','lib-rename-folder','',can&&!own.system?'':'disabled'):'')+(space==='项目空间'&&!m.reference?B(I('link')+'引入外部文件夹','lib-import-folder','',can?'':'disabled'):'')+(m.reference?B('取消引入','lib-remove-reference','',own.reference?'':'disabled'):'')+(path?B(I('settings')+'权限设置','lib-permissions','',can?'':'disabled'):'')+(space==='项目空间'&&!path?B(I('users')+'查看审计小组','lib-groups'):'')+(state.libraryAdmin&&path?B('机构与项目绑定','lib-bind')+(can&&!own.system?B('移动文件夹','lib-move-folder')+B('同级上移','lib-folder-up')+B('同级下移','lib-folder-down'):''):'')+(path&&!m.reference?B(I('trash')+'删除文件夹','lib-delete-folder','danger',can&&!own.system?'':'disabled'):'')+'</div>',B('关闭','close-modal'),'small');}
 if(modal==='lib-delete')return modalFrame(d.folder?'删除文件夹':'删除资料',d.folder?E(d.space+' / '+d.path):'请核对本次删除范围',libDeleteBody(selectedDocs(d.ids)),B('取消','close-modal')+B('确认删除','lib-confirm-delete','danger',d.ids.every(id=>libCanEdit(file(id)))?'':'disabled'),'medium');
 if(modal==='lib-move')return modalFrame('移动文件','移动后已有任务的资料引用不变。','<p class="small mb">已选 '+d.ids.length+' 份资料</p><label class="field">目标空间<select id="lib-move-space" data-lib-change="move-space">'+options(SPACE_ORDER,d.space)+'</select></label><label class="field">目标文件夹<select id="lib-move-target">'+libTargetOptions(d.space)+'</select></label>'+libErrorHtml,B('取消','close-modal')+B('确认移动','lib-confirm-move','primary'),'small');
 if(modal==='lib-download-text')return modalFrame('下载资料内容',E(file(d.id).name),'<p>当前保存了该资料的正文内容，可下载为文本。需要原版式文件时，请补充原始文件。</p>',B('取消','close-modal')+B('下载正文（TXT）','lib-download-text-confirm','primary'),'small');
 if(modal==='lib-reparse')return modalFrame('重新解析','已解析完成的文件不重复处理。','<div class="lib-confirm-list">'+selectedDocs(d.ids).map(f=>'<div>'+E(f.name)+' '+libStatusTag(f)+'</div>').join('')+'</div><p class="hint">重新读取原始文件；既有分析结果不会自动更新。</p>',B('取消','close-modal')+B('确认重新解析','lib-confirm-reparse','primary'),'medium');
 if(modal==='lib-reselect')return modalFrame('重新选择原文件',E(file(d.id).name),'<p class="hint mb">请选择名称一致的原文件，解析后再发起分析。</p><input type="file" id="lib-reselect-file">'+libErrorHtml,B('关闭','close-modal'),'small');
 if(modal==='lib-upload-types')return modalFrame('上传文件夹 · 选择文件类型','保留原目录层级，仅上传勾选的文件类型。',simpleTable(['上传','文件类型','数量','大小'],d.types.map(type=>{const files=d.files.filter(f=>f.name.split('.').at(-1).toLowerCase()===type);return ['<input type="checkbox" aria-label="上传 '+E(type)+' 文件" data-lib-change="upload-type" value="'+E(type)+'" '+(d.selected.includes(type)?'checked':'')+'>',E(type.toUpperCase()),files.length,libFormat(files.reduce((n,f)=>n+f.size,0))];}),true)+'<p class="hint mt">已选 '+d.files.filter(f=>d.selected.includes(f.name.split('.').at(-1).toLowerCase())).length+' 个文件</p>',B('取消','close-modal')+B('继续上传','lib-upload-types-next','primary',d.selected.length?'':'disabled'),'medium');
 if(modal==='lib-upload-conflicts')return modalFrame('处理重名文件','同名文件夹会合并；覆盖前请核对资料版本。',simpleTable(['文件路径','处理方式'],d.entries.filter(e=>e.oldId||e.duplicate).map(e=>[E(e.name),'<select aria-label="'+E(e.name)+' 的重名处理" data-lib-change="conflict" data-index="'+e.index+'"><option value="skip" '+(e.choice==='skip'?'selected':'')+'>跳过</option>'+(!e.duplicate?'<option value="replace" '+(e.choice==='replace'?'selected':'')+'>覆盖</option>':'')+'</select>']),true)+'<p class="hint mt">同批重复文件仅保留第一份。已有任务保留原版本引用。</p>',B('取消上传','close-modal')+B('确认上传','lib-upload-conflicts-confirm','primary'),'medium');
 if(modal==='lib-permissions'){const m=libMeta(d.space,d.path);return modalFrame('文件夹权限',E(d.space+' / '+d.path),libPermissionRows(m)+'<h3 class="mt mb">新增授权</h3><div class="lib-form-grid"><label class="field">对象类型<select id="lib-grant-type"><option value="USER">用户</option><option value="ORG">机构</option></select></label>'+libForm('授权对象','lib-grant-name','','placeholder="输入用户或机构名称"')+'<label class="field">权限级别<select id="lib-grant-level" data-lib-change="grant-level"><option value="READ">查看</option><option value="MANAGE" '+(d.grantLevel==='MANAGE'?'selected':'')+'>管理</option></select></label><label class="row-radio"><input type="checkbox" id="lib-grant-descendants">包含下级机构</label><label class="row-radio"><input type="checkbox" id="lib-grant-delegate" '+(d.grantLevel==='MANAGE'?'':'disabled')+'>允许分权（管理权限）</label></div>'+libErrorHtml,B('关闭','close-modal')+B('新增授权','lib-save-grant','primary'),'medium');}
 if(modal==='lib-revoke-confirm')return modalFrame('撤销授权',E(d.grant.name),'<p>撤销后，该对象将不再通过此授权访问文件夹。其他有效授权仍按原设置保留。</p>',B('取消','lib-permissions-back')+B('确认撤销','lib-revoke-confirm','danger'),'small');
 if(modal==='lib-import-folder'){const source=d.sourceSpace||'公共空间';return modalFrame('引入外部文件夹','目标：'+E(d.space+' / '+(d.path||'根目录')),'<label class="field">来源空间<select data-lib-change="reference-space">'+options(['公共空间','个人空间'],source)+'</select></label><label class="field">来源文件夹<select id="lib-reference-path">'+directoryPaths(source).filter(p=>!libInherited(source,p).reference&&libInherited(source,p).permission!=='NONE').map(p=>'<option value="'+E(p)+'">'+E(p)+'</option>').join('')+'</select></label><p class="hint">引入后以只读目录浏览，不复制或修改源资料；取消引入只移除引用。</p>'+libErrorHtml,B('取消','close-modal')+B('确认引入','lib-confirm-import','primary'),'medium');}
 if(modal==='lib-remove-reference')return modalFrame('取消引入',E(d.path),'<p>仅移除项目空间中的引用目录，源空间文件夹及文件保留。</p>',B('取消','close-modal')+B('确认取消引入','lib-confirm-remove-reference','danger'),'small');
 if(modal==='lib-groups')return modalFrame('审计小组','园区改造项目',simpleTable(['小组名称','组长','组长角色','成员数','创建时间'],[['项目审计组','李明','审计组长','6','2026-01-10']])+'<p class="hint mt">成员与角色在项目管理中维护，目录授权不能替代项目角色权限。</p>',B('关闭','close-modal'),'medium');
 if(modal==='lib-bind')return modalFrame('机构与项目绑定',E(d.path),libForm('绑定机构','lib-bound-org',libMeta(d.space,d.path).boundOrg||'')+libForm('绑定项目','lib-bound-project',libMeta(d.space,d.path).boundProject||'')+'<label class="row-radio"><input type="checkbox" id="lib-bound-grant">为绑定机构授予查看权限</label><label class="row-radio"><input type="checkbox" id="lib-bound-descendants">包含下级机构</label><p class="hint mt">清空对应字段可解除绑定。机构根目录下不能直接新建子目录。</p>'+libErrorHtml,B('取消','close-modal')+B('保存绑定','lib-save-bind','primary'),'medium');
 if(modal==='lib-storage'){const spaces=SPACE_ORDER,stats=spaces.map(s=>{const docs=state.docs.filter(f=>!f.deleted&&!f.refSourceId&&f.space===s);return[s,docs.length,libFormat(docs.reduce((n,f)=>n+libSize(f),0))];});return modalFrame('空间用量','引用资料不重复计入当前空间用量。',simpleTable(['空间','文件数','已用空间'],stats)+(state.libraryAdmin?'<h3 class="mt">用户存储额度</h3>'+libForm('用户','lib-quota-user','当前用户')+libForm('额度（GB）','lib-quota',String(storageQuota.personal),'type="number" min="0.01" step="0.01"'):'<p class="hint mt">个人空间额度：'+storageQuota.personal+' GB。额度由文件管理员维护。</p>')+libErrorHtml,B('关闭','close-modal')+(state.libraryAdmin?B('保存额度','lib-save-quota','primary'):''),'medium');}
 if(modal==='lib-tool-handoff')return modalFrame('确认分析资料',tool(d.toolId).name,'<p class="mb">符合要求 '+d.accepted.length+' 份；以下 '+d.excluded.length+' 份未纳入本次分析。</p>'+simpleTable(['资料','原因'],d.excluded.map(x=>[x.doc.name,x.reason]))+'<p class="hint mt">资料管理中的已选清单保持不变，可先处理解析问题或补充适用资料。</p>',B('返回检查','close-modal')+B('使用 '+d.accepted.length+' 份继续','lib-confirm-handoff','primary',d.accepted.length?'':'disabled'),'medium');
 if(modal==='lib-search')return libSearchModal();
 return libraryBase.modalContent();
};

function libNameSave(){const d=modalData,name=$('#lib-name').value.trim();if(!name||/[\\/:*?"<>|\x00-\x1f]/.test(name)||['.','..'].includes(name))return libError('请输入有效名称，不含斜杠或特殊符号。');if(!libWritable(d.space,d.path))return libError('当前目录没有修改权限。');if(d.create||d.folder){const parent=d.create?folderPath(d.path):folderPath(d.path).split('/').slice(0,-1).join('/'),next=[parent,name].filter(Boolean).join('/');if(next===d.path){closeModal();return;}if(directoryPaths(d.space).includes(next)||state.docs.some(f=>!f.deleted&&f.space===d.space&&folderPath(f.folder)===parent&&f.name===name))return libError('同一目录下已存在此名称。');if(d.folder){const old=d.path;libUpdateReferencePaths(d.space,old,next);if(d.space==='项目空间')state.customFolders=(state.customFolders||[]).map(p=>underFolder(p,old)?next+p.slice(old.length):p);state.docs.filter(f=>f.space===d.space&&underFolder(f.folder,old)).forEach(f=>f.folder=next+folderPath(f.folder).slice(old.length));state.directoryNodes.filter(n=>n.space===d.space&&underFolder(n.path,old)).forEach(n=>n.path=next+n.path.slice(old.length));Object.entries(folderMeta).filter(([k])=>k.startsWith(d.space+'::')&&underFolder(k.split('::')[1],old)).forEach(([k,m])=>{folderMeta[directoryKey(d.space,next+k.split('::')[1].slice(old.length))]=m;delete folderMeta[k];});}state.directoryNodes.push({space:d.space,path:next});state.folder=next;state.space=d.space;}
 else{const f=file(d.id);if(!libCanEdit(f))return libError('此文件为只读。');if(name.split('.').at(-1).toLowerCase()!==f.name.split('.').at(-1).toLowerCase())return libError('请保留原文件扩展名。');if(state.docs.some(x=>!x.deleted&&x.id!==f.id&&x.space===f.space&&folderPath(x.folder)===folderPath(f.folder)&&x.name.toLowerCase()===name.toLowerCase()))return libError('同一目录下已存在同名文件。');f.name=name;f.title=name.replace(/\.[^.]+$/,'');}closeModal();render();toast('已保存。');}
function libHandoff(toolId,ids){fullResult=false;const prior=state.librarySelected;state.librarySelected=ids;libraryBase.handleAction('open-tool',{dataset:{id:toolId}});state.librarySelected=prior;persist();}
function libEligible(d,id){if(!libReady(d))return libStatus(d);const ext=d.name.split('.').at(-1).toLowerCase(),allowed=['engineering','association'].includes(id)?['xls','xlsx','csv']:['meeting','contract','timeline','prepaid'].includes(id)?['pdf','doc','docx','wps']:id==='risk'?['pdf','doc','docx']:null;return allowed&&!allowed.includes(ext)?'该工具不支持此文件类型':'';}
async function libReparse(ids){closeModal();for(const id of ids){const doc=file(id);if(!doc||!libCanParse(doc))continue;const source=await libGetFile(id);if(!source){openModal('lib-reselect',{id,remaining:ids.slice(ids.indexOf(id)+1)});return;}doc.local=true;doc.parseError=null;uploadSources.set(id,source);const record=state.uploads.find(u=>u.id===id)||{id,name:doc.name,target:doc.space+' / '+doc.folder,time:new Date().toLocaleString('zh-CN')};if(!state.uploads.includes(record))state.uploads.unshift(record);record.cancelPending=false;record.queueCleared=false;record.failedQueueCleared=false;record.contentStatus=null;doc.content_status=null;record.error=null;await parseUploadRecord(record,doc,source);}render();}
function libFolderContext(){return{space:modalData.space||state.space,path:folderPath(modalData.path??state.folder)};}
function libDelete(ids,extra={}){openModal('lib-delete',{ids,...extra});}
handleAction=function(action,el){const id=el?.dataset.id;
 if(action==='folder'&&!libReadable(state.space,id)){toast('当前文件夹没有查看权限。');return;}
 if(action==='source'&&state.view==='library'){const f=file(id);if(f){f.lastViewed=new Date().toISOString();persist();}if(modal&&modal!=='picker'&&modal!=='source')libraryReturn={type:modal,data:modalData};}
 if(action==='close-modal'&&modal==='upload-records'&&recordsAutoTimer){clearInterval(recordsAutoTimer);recordsAutoTimer=null;}
 if(action==='close-modal'&&modal==='lib-search'&&modalData.worker){modalData.worker.terminate();}
 if(action==='upload'&&state.view==='library'&&!libWritable()){toast('当前目录只读，请选择可上传目录。');return;}
 if(action==='open-tool'&&state.view==='library'&&state.librarySelected.length){const docs=libSelected(),accepted=docs.filter(d=>!libEligible(d,id)).map(d=>d.refSourceId||d.id),excluded=docs.filter(d=>libEligible(d,id)).map(doc=>({doc,reason:libEligible(doc,id)}));if(excluded.length){openModal('lib-tool-handoff',{toolId:id,accepted:[...new Set(accepted)],excluded});return;}libHandoff(id,[...new Set(accepted)]);return;}
 if(!action.startsWith('lib-'))return libraryBase.handleAction(action,el);
 switch(action){
 case 'lib-toggle-folders':if(innerWidth<=760)libraryPrefs.mobileFolderOpen=!libraryPrefs.mobileFolderOpen;else libraryPrefs.showFolders=!libraryPrefs.showFolders;render();break;
 case 'lib-toggle-tools':libraryPrefs.showTools=!libraryPrefs.showTools;render();break;
 case 'lib-tree-mode':libraryPrefs.focused=!libraryPrefs.focused;if(libraryPrefs.focused){directoryPaths(state.space).forEach(p=>{if(!underFolder(state.folder,p))treeClosed.add('library::'+directoryKey(state.space,p));});}else{directoryPaths(state.space).forEach(p=>treeClosed.delete('library::'+directoryKey(state.space,p)));}render();toast(libraryPrefs.focused?'已聚焦当前目录路径。':'已展开完整目录。');break;
 case 'lib-refresh':render();toast('目录与文件列表已刷新，已选清单保留。');break;
 case 'lib-reset':state.query='';libraryFilters.status='';libraryFilters.type='';state.page=1;render();break;
 case 'lib-clear-selection-modal':state.librarySelected=[];render();paintModal();break;
 case 'lib-create-folder':if(!libWritable()||libMeta(state.space,state.folder).boundOrg){toast('当前目录不允许新建子文件夹。');return;}openModal('lib-name',{create:true,space:state.space,path:folderPath(state.folder),value:''});break;
 case 'lib-folder-menu':openModal('lib-folder-menu',{space:state.space,path:folderPath(el.dataset.path)});break;
 case 'lib-create-at':{const c=libFolderContext();if(!libWritable(c.space,c.path)||libMeta(c.space,c.path).boundOrg)return toast('当前目录不允许新建子文件夹。');openModal('lib-name',{...c,create:true,value:''});break;}
 case 'lib-rename-folder':{const c=libFolderContext();if(!libWritable(c.space,c.path)||!c.path||libMeta(c.space,c.path).system)return;openModal('lib-name',{...c,folder:true,value:folderName(c.path)});break;}
 case 'lib-rename-file':{const f=file(id);if(!libCanEdit(f))return;openModal('lib-name',{id,space:f.space,path:folderPath(f.folder),value:f.name});break;}
 case 'lib-save-name':libNameSave();break;
 case 'lib-download':libDownload(file(id));break;
 case 'lib-download-text-confirm':{const f=file(modalData.id);download(f.name.replace(/\.[^.]+$/,'')+'.txt',f.text);closeModal();break;}
 case 'lib-attachments':openModal('lib-attachments',{id});break;
 case 'lib-pick-attachment':if(libCanEdit(file(id)))startPicker({main:id,selected:[...(file(id).attachments||[])]});break;
 case 'lib-unlink':{const f=file(el.dataset.main);if(!libCanEdit(f))return;f.attachments=(f.attachments||[]).filter(x=>x!==id);persist();paintModal();render();toast('已移除附件关联，原文件保留。');break;}
 case 'lib-delete-file':libDelete([id]);break;
 case 'lib-delete-selected':libDelete(libSelected().map(d=>d.id));break;
 case 'lib-delete-folder':{const c=libFolderContext();if(!libWritable(c.space,c.path)||!c.path||libMeta(c.space,c.path).system)return;libDelete(inDirectory(c.space,c.path,true).map(d=>d.id),{...c,folder:true});break;}
 case 'lib-confirm-delete':{const d=modalData;if(d.folder&&(!d.path||!libWritable(d.space,d.path)||libMeta(d.space,d.path).system))return;if(d.ids.some(id=>!libCanEdit(file(id))))return libError('包含无权删除的文件，请调整选择。');const old=d.ids.map(file),directorySnapshot=structuredClone(state.directoryNodes),metaSnapshot=structuredClone(folderMeta);old.forEach(f=>f.deleted=true);libPruneDrafts(d.ids);state.librarySelected=state.librarySelected.filter(id=>!d.ids.includes(id));if(d.folder){state.directoryNodes=state.directoryNodes.filter(n=>n.space!==d.space||!underFolder(n.path,d.path));if(d.space==='项目空间')state.customFolders=(state.customFolders||[]).filter(p=>!underFolder(p,d.path));Object.keys(folderMeta).forEach(k=>{if(k.startsWith(d.space+'::')&&underFolder(k.split('::')[1],d.path))delete folderMeta[k];});if(state.space===d.space&&underFolder(state.folder,d.path))state.folder=d.path.split('/').slice(0,-1).join('/')||'全部资料';}closeModal();render();toast('已删除资料。',()=>{old.forEach(f=>f.deleted=false);state.directoryNodes=directorySnapshot;folderMeta=metaSnapshot;render();});break;}
 case 'lib-move-file':if(libCanEdit(file(id)))openModal('lib-move',{ids:[id],space:file(id).space});break;
 case 'lib-move-selected':{const docs=libSelected();if(docs.some(d=>!libCanEdit(d)))return toast('所选资料中包含只读文件，请先取消选择。');openModal('lib-move',{ids:docs.map(d=>d.id),space:state.space});break;}
 case 'lib-confirm-move':{const d=modalData,space=$('#lib-move-space').value,path=$('#lib-move-target').value;if(!libWritable(space,path))return libError('目标目录没有写入权限。');if(d.ids.some(id=>!libCanEdit(file(id))))return libError('所选文件没有移动权限。');const names=new Set();for(const f of selectedDocs(d.ids)){const key=f.name.toLowerCase();if(names.has(key)||state.docs.some(x=>!x.deleted&&!d.ids.includes(x.id)&&x.space===space&&folderPath(x.folder)===path&&x.name.toLowerCase()===key))return libError('目标目录有重名文件，请先重命名后移动。');names.add(key);}selectedDocs(d.ids).forEach(f=>{f.space=space;f.folder=path||'根目录';});closeModal();render();toast('文件已移动，原分析引用保留。');break;}
 case 'lib-reparse':{const ids=libSelected().filter(d=>(d.local||d.parseError)&&libCanParse(d)).map(d=>d.id);if(!ids.length)return toast('没有可重新解析的文件。');openModal('lib-reparse',{ids});break;}
 case 'lib-confirm-reparse':libReparse([...modalData.ids]);break;
 case 'lib-upload-types-next':{const d=modalData,files=d.files.filter(f=>d.selected.includes(f.name.split('.').at(-1).toLowerCase()));libUploadConflicts(files);break;}
 case 'lib-upload-conflicts-confirm':{const d=modalData,entries=d.entries.filter(e=>e.choice!=='skip');if(!entries.length){closeModal();toast('已跳过全部重名文件。');return;}const files=entries.map(e=>d.files[e.index]),overwrite=entries.filter(e=>e.choice==='replace').map(e=>e.oldId);openModal('upload',{items:[]});libUploadCommit(files,overwrite);break;}
 case 'lib-permissions':{const c=libFolderContext();if(!libWritable(c.space,c.path))return;openModal('lib-permissions',c);break;}
 case 'lib-save-grant':{const d=modalData;if(!libWritable(d.space,d.path))return;const name=$('#lib-grant-name').value.trim(),type=$('#lib-grant-type').value,level=$('#lib-grant-level').value;if(!name||name.length>80)return libError('请填写有效的授权对象。');const m=folderMeta[directoryKey(d.space,d.path)]??={};m.grants??=[];if(m.grants.some(g=>g.name===name&&g.type===type))return libError('该对象已获授权，请先撤销原授权再调整。');m.grants.push({name,type,level,delegate:level==='MANAGE'&&$('#lib-grant-delegate').checked,descendants:type==='ORG'&&$('#lib-grant-descendants').checked,grantedAt:new Date().toISOString()});persist();paintModal();toast('授权已保存。');break;}
 case 'lib-revoke':{const c={...modalData},grant=libMeta(c.space,c.path).grants?.[+el.dataset.index];if(grant)openModal('lib-revoke-confirm',{...c,index:+el.dataset.index,grant});break;}
 case 'lib-permissions-back':openModal('lib-permissions',libFolderContext());break;
 case 'lib-revoke-confirm':{const d=modalData;if(!libWritable(d.space,d.path))return;libMeta(d.space,d.path).grants.splice(d.index,1);persist();openModal('lib-permissions',libFolderContext());toast('授权已撤销。');break;}
 case 'lib-import-folder':{const c=libFolderContext();if(c.space==='项目空间'&&libWritable(c.space,c.path))openModal('lib-import-folder',{...c,sourceSpace:'公共空间'});break;}
 case 'lib-confirm-import':{const d=modalData,source=d.sourceSpace||'公共空间',path=$('#lib-reference-path')?.value;if(!path||!libWritable(d.space,d.path))return libError('请选择有访问权限的来源文件夹。');const target=[d.path,folderName(path)].filter(Boolean).join('/');if(directoryPaths(d.space).includes(target))return libError('目标目录已有同名文件夹，请先调整目录名称。');folderMeta[directoryKey(d.space,target)]={reference:{space:source,path},permission:'READ'};state.directoryNodes.push({space:d.space,path:target});state.docs.filter(f=>!f.deleted&&f.space===source&&underFolder(f.folder,path)).forEach(f=>state.docs.push({...structuredClone(f),id:'ref-'+Date.now()+'-'+f.id,space:d.space,folder:target+folderPath(f.folder).slice(path.length),refSourceId:f.refSourceId||f.id}));state.space=d.space;state.folder=target;closeModal();render();toast('已引入只读目录，源资料保留。');break;}
 case 'lib-remove-reference':{const c=libFolderContext();if(libMeta(c.space,c.path).reference)openModal('lib-remove-reference',c);break;}
 case 'lib-confirm-remove-reference':{const d=modalData;if(!libMeta(d.space,d.path).reference)return;state.docs.filter(f=>f.space===d.space&&underFolder(f.folder,d.path)&&f.refSourceId).forEach(f=>{f.deleted=true;f.referenceInactive=true;});state.directoryNodes=state.directoryNodes.filter(n=>n.space!==d.space||!underFolder(n.path,d.path));delete folderMeta[directoryKey(d.space,d.path)];state.librarySelected=state.librarySelected.filter(id=>file(id)&&!file(id).deleted);if(underFolder(state.folder,d.path))state.folder=d.path.split('/').slice(0,-1).join('/')||'全部资料';closeModal();render();toast('已取消引入，源目录未改变。');break;}
 case 'lib-groups':openModal('lib-groups',libFolderContext());break;
 case 'lib-bind':if(state.libraryAdmin)openModal('lib-bind',libFolderContext());break;
 case 'lib-save-bind':{if(!state.libraryAdmin)return;const d=modalData,m=folderMeta[directoryKey(d.space,d.path)]??={};m.boundOrg=$('#lib-bound-org').value.trim();m.boundProject=$('#lib-bound-project').value.trim();if(m.boundOrg&&$('#lib-bound-grant').checked){m.grants??=[];m.grants.push({type:'ORG',name:m.boundOrg,level:'READ',descendants:$('#lib-bound-descendants').checked});}closeModal();render();toast('绑定已保存。');break;}
 case 'lib-storage':openModal('lib-storage');break;
 case 'lib-save-quota':{if(!state.libraryAdmin)return;const n=+$('#lib-quota').value,name=$('#lib-quota-user').value.trim();if(!name||!Number.isFinite(n)||n<.01||n>100000)return libError('请输入用户和有效额度，最小0.01 GB。');if(name==='当前用户')storageQuota.personal=n;else{storageQuota.users=storageQuota.users.filter(u=>u.name!==name);storageQuota.users.push({name,limit:n});}persist();toast('存储额度已保存。');break;}
 case 'lib-confirm-handoff':{const d=modalData;closeModal();libHandoff(d.toolId,d.accepted);break;}
 case 'lib-search':openModal('lib-search',{ids:libSelected().filter(libReady).map(f=>f.id),selected:[],keyword:'',regex:false,hits:null,preview:null});break;
 case 'lib-search-pick':{const old=modalData;old.worker?.terminate();delete old.worker;old.busy=false;startPicker({selected:[...old.ids],libraryTextSearch:old});break;}
 case 'lib-search-run':libSearchRun();break;
 case 'lib-search-clear':modalData.worker?.terminate();delete modalData.worker;modalData.busy=false;modalData.hits=null;modalData.keyword='';modalData.selected=[];paintModal();break;
 case 'lib-search-preview':modalData.preview=id;paintModal();break;
 case 'lib-search-export':libSearchExport(el.dataset.format);break;
 case 'lib-search-tool':{const d=modalData,ids=[...d.selected];closeModal();state.librarySelected=[...new Set([...state.librarySelected,...ids])];handleAction('open-tool',{dataset:{id}});break;}
 }
};
closeModal=function(){if(modal==='source'&&libraryReturn){const back=libraryReturn;libraryReturn=null;openModal(back.type,back.data);return;}if(modal==='lib-search'&&modalData.worker)modalData.worker.terminate();libraryBase.closeModal();if(state.view==='library')render();};
const libraryPickerAction=handleAction;
handleAction=function(action,el){if(action==='confirm-picker'&&modalData.selected)modalData.selected=[...new Set(modalData.selected.map(id=>file(id)?.refSourceId||id))];if(action==='confirm-picker'&&modalData.libraryTextSearch){const old=modalData.libraryTextSearch;old.ids=[...modalData.selected];old.hits=null;old.selected=[];openModal('lib-search',old);return;}return libraryPickerAction(action,el);};

// Content search is scoped explicitly. Regex runs in a terminable worker so a bad expression cannot freeze the page.
function libSearchRows(){return modalData.hits||selectedDocs(modalData.ids).map(d=>({id:d.id,snippet:'',count:0}));}
function libSearchModal(){const p=modalData,rows=libSearchRows(),preview=rows.find(r=>r.id===p.preview)||rows[0],f=preview&&file(preview.id);return modalFrame('文本检索','选择检索资料 → 输入关键词 → 核验匹配原文 → 导出或继续分析','<div class="lib-text-toolbar"><input id="lib-text-query" aria-label="正文检索关键词" placeholder="输入关键词或正则表达式" value="'+E(p.keyword)+'" data-lib-input="text-keyword"><label class="row-radio"><input type="checkbox" data-lib-change="regex" '+(p.regex?'checked':'')+'>正则</label>'+B(p.busy?'检索中…':'开始检索','lib-search-run','primary sm',p.busy?'disabled':'')+B('选择资料（'+p.ids.length+'）','lib-search-pick','sm')+B('清空检索','lib-search-clear','sm')+'</div>'+libErrorHtml+'<div class="lib-text-actions"><span>'+(p.hits?'匹配 '+rows.length+' 份 / 范围 '+p.ids.length+' 份':'检索范围 '+p.ids.length+' 份')+' · 已选 '+p.selected.length+' 份</span><div class="row">'+B('导出 Excel','lib-search-export','sm','data-format="xlsx" '+(p.selected.length?'':'disabled'))+B('导出 Word','lib-search-export','sm','data-format="word" '+(p.selected.length?'':'disabled'))+'<select aria-label="将检索结果带入工具" data-lib-change="search-tool" '+(p.selected.length?'':'disabled')+'><option value="">选择分析工具</option>'+TOOLS.map(t=>'<option value="'+t.id+'">'+E(t.name)+'</option>').join('')+'</select></div></div><div class="lib-text-layout"><div class="lib-text-list"><label class="row-radio lib-text-selectall"><input type="checkbox" data-lib-change="search-page" '+(rows.length&&rows.every(r=>p.selected.includes(r.id))?'checked':'')+'>全选当前结果</label>'+rows.map(r=>'<div class="lib-text-item '+(preview?.id===r.id?'active':'')+'"><input type="checkbox" aria-label="选择检索结果 '+E(file(r.id).name)+'" data-lib-change="search-check" data-id="'+r.id+'" '+(p.selected.includes(r.id)?'checked':'')+'><button data-action="lib-search-preview" data-id="'+r.id+'"><b>'+E(file(r.id).name)+'</b><small>'+E(r.snippet||file(r.id).space+' / '+file(r.id).folder)+'</small></button></div>').join('')+(!rows.length?'<div class="compact-empty">'+(p.hits?'没有匹配的资料。':'请先选择资料。')+'</div>':'')+'</div><div class="lib-text-preview">'+(f?'<div class="row between mb"><h3>'+E(f.name)+'</h3>'+A('查看完整原文','source',libAttrs(f))+'</div><div class="lib-match-snippet">'+(preview.start!=null?'<span>'+E(preview.prefix)+'</span><mark>'+E(preview.match)+'</mark><span>'+E(preview.suffix)+'</span>':'<p class="hint">输入关键词检索正文；文件名称搜索位于资料列表上方。</p>')+'</div><pre>'+E(f.text||'未读取到正文，请先完成解析。')+'</pre>':'<div class="compact-empty">选择左侧文件，核验正文与匹配位置。</div>')+'</div></div>',B('关闭','close-modal'),'lib-search-dialog');}
async function libSearchRun(){const p=modalData;if(p.busy)return;const keyword=$('#lib-text-query').value.trim();if(!p.ids.length)return libError('请先选择需要检索的资料。');if(!keyword)return libError('请输入检索关键词。');p.keyword=keyword;p.busy=true;p.selected=[];p.hits=null;paintModal();const source=`onmessage=e=>{try{const {docs,keyword,regex}=e.data;const expression=regex?new RegExp(keyword,'iu'):null;const hits=[];for(const d of docs){const m=expression?expression.exec(d.text):null;const start=regex?(m?m.index:-1):d.text.toLocaleLowerCase().indexOf(keyword.toLocaleLowerCase());if(start>=0){const match=regex?m[0]:d.text.slice(start,start+keyword.length),prefix=d.text.slice(Math.max(0,start-80),start),suffix=d.text.slice(start+match.length,start+match.length+140);hits.push({id:d.id,start,match,prefix,suffix,snippet:prefix+match+suffix});}}postMessage({hits});}catch(err){postMessage({error:'正则表达式无效，请检查后重试。'});}}`;
 const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'})),worker=new Worker(url);URL.revokeObjectURL(url);p.worker=worker;const timer=setTimeout(()=>{worker.terminate();if(modal==='lib-search'&&modalData===p){p.busy=false;delete p.worker;paintModal();libError('检索表达式耗时过长，请简化表达式或缩小资料范围。');}},1500);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();delete p.worker;if(modal!=='lib-search'||modalData!==p)return;p.busy=false;p.hits=e.data.hits||[];p.preview=p.hits[0]?.id;paintModal();if(e.data.error)libError(e.data.error);};worker.onerror=()=>{clearTimeout(timer);worker.terminate();if(modal==='lib-search'&&modalData===p){p.busy=false;paintModal();libError('检索未完成，请重试。');}};worker.postMessage({docs:selectedDocs(p.ids).map(d=>({id:d.id,text:d.text||''})),keyword,regex:p.regex});}
function libSearchExport(format){const p=modalData,rows=[['文件名称','位置','关键词','匹配内容'],...libSearchRows().filter(r=>p.selected.includes(r.id)).map(r=>{const f=file(r.id);return[f.name,f.space+' / '+f.folder,p.keyword,r.snippet||f.text||''];})];if(format==='xlsx'){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),'文本检索');XLSX.writeFile(wb,'文本检索结果.xlsx');}else download('文本检索结果.doc','<!doctype html><html><head><meta charset="UTF-8"></head><body><h1>文本检索结果</h1><table border="1">'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+E(v)+'</td>').join('')+'</tr>').join('')+'</table></body></html>','application/msword');}

document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.libInput||el.dataset.libInput==='record-query')return;e.stopImmediatePropagation();if(el.dataset.libInput==='text-keyword'){modalData.keyword=el.value;return;}state.query=el.value;state.page=1;const pos=el.selectionStart;render();const next=$('#lib-file-query');next?.focus();next?.setSelectionRange(pos,pos);},true);
document.addEventListener('change',async e=>{const el=e.target,k=el.dataset.libChange;if(el.id==='lib-reselect-file'){e.stopImmediatePropagation();const doc=file(modalData.id),source=el.files[0];if(!source)return;if(source.name!==doc.name)return libError('文件名不一致，请选择 '+doc.name);uploadSources.set(doc.id,source);await libStoreFile(doc.id,source);doc.byteSize=source.size;const remaining=[...(modalData.remaining||[])],record=state.uploads.find(u=>u.id===doc.id)||{id:doc.id,name:doc.name,target:doc.space+' / '+doc.folder,time:new Date().toLocaleString('zh-CN')};if(!state.uploads.includes(record))state.uploads.unshift(record);closeModal();await parseUploadRecord(record,doc,source);render();if(remaining.length)await libReparse(remaining);return;}if(!k||k.startsWith('record-'))return;e.stopImmediatePropagation();switch(k){
 case 'space':state.space=el.value;state.folder='全部资料';state.page=1;state.query='';folderQueries.library='';render();break;
 case 'scope':state.libraryRecursive=el.value==='recursive';state.page=1;render();break;
 case 'status':libraryFilters.status=el.value==='全部状态'?'':el.value;state.page=1;render();break;
 case 'type':libraryFilters.type=el.value;state.page=1;render();break;
 case 'sort':librarySort=el.value;state.page=1;render();break;
 case 'size':libraryPrefs.pageSize=+el.value;state.page=1;render();break;
 case 'check':state.librarySelected=el.checked?[...new Set([...state.librarySelected,el.dataset.id])]:state.librarySelected.filter(id=>id!==el.dataset.id);render();break;
 case 'page':{const ids=pageItems(libItems(),state.page,libraryPrefs.pageSize).filter(x=>x.kind==='file').map(x=>x.file.id);state.librarySelected=el.checked?[...new Set([...state.librarySelected,...ids])]:state.librarySelected.filter(id=>!ids.includes(id));render();break;}
 case 'move-space':modalData.space=el.value;paintModal();break;
 case 'upload-type':modalData.selected=el.checked?[...modalData.selected,el.value]:modalData.selected.filter(x=>x!==el.value);paintModal();break;
 case 'conflict':modalData.entries[+el.dataset.index].choice=el.value;break;
 case 'reference-space':modalData.sourceSpace=el.value;paintModal();break;
 case 'grant-level':$('#lib-grant-delegate').disabled=el.value!=='MANAGE';if(el.value!=='MANAGE')$('#lib-grant-delegate').checked=false;modalData.grantLevel=el.value;break;
 case 'regex':modalData.regex=el.checked;break;
 case 'search-check':modalData.selected=el.checked?[...new Set([...modalData.selected,el.dataset.id])]:modalData.selected.filter(id=>id!==el.dataset.id);paintModal();break;
 case 'search-page':modalData.selected=el.checked?libSearchRows().map(r=>r.id):[];paintModal();break;
 case 'search-tool':if(el.value)handleAction('lib-search-tool',{dataset:{id:el.value}});break;
 }},true);
document.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Enter'&&e.target.id==='lib-name'){e.preventDefault();libNameSave();}if(e.key==='Enter'&&e.target.id==='lib-text-query'){e.preventDefault();libSearchRun();}});
// Keep reference views current without duplicating source changes or promoting permissions.
const libRender=render;
render=function(){Object.entries(folderMeta).filter(([,m])=>m.reference).forEach(([key,m])=>{const [space,target]=key.split('::'),src=m.reference;state.docs.filter(f=>!f.deleted&&!f.refSourceId&&f.space===src.space&&underFolder(f.folder,src.path)).forEach(f=>{const path=target+folderPath(f.folder).slice(src.path.length);let ref=state.docs.find(d=>!d.referenceInactive&&d.refSourceId===f.id&&d.space===space&&underFolder(d.folder,target));if(!ref){ref={...structuredClone(f),id:'ref-'+Date.now()+'-'+f.id+'-'+Math.random().toString(36).slice(2,7),space,folder:path,refSourceId:f.id};state.docs.push(ref);}else ref.folder=path;});});state.docs.filter(d=>d.refSourceId&&!d.referenceInactive).forEach(d=>{const source=file(d.refSourceId),reference=libInherited(d.space,d.folder).reference;if(!reference||!source||source.space!==reference.space||!underFolder(source.folder,reference.path)){d.deleted=true;return;}if(source){const {id,space,folder,refSourceId}=d;Object.assign(d,structuredClone(source),{id,space,folder,refSourceId});}else d.deleted=true;});libRender();const boxes=$$('.lib-table input[data-lib-change="check"]'),all=$('.lib-table input[data-lib-change="page"]');if(all)all.indeterminate=boxes.some(b=>b.checked)&&!boxes.every(b=>b.checked);};
render();

// Upload records share the parsing state shown in the file browser.
const recordsBase={modalContent,handleAction,parseUploadRecord};
let recordsAutoTimer=null;
function libRecordRows(){const p=modalData;return state.docs.filter(d=>!d.deleted&&!d.refSourceId&&(p.space==='全部空间'||d.space===p.space)&&(!p.query||d.name.toLowerCase().includes(p.query.toLowerCase()))&&(!p.status||libStatus(d)===p.status)&&(!p.source||(d.source||'LOCAL')===p.source)).map(doc=>({doc,record:state.uploads.find(u=>u.id===doc.id)}));}
modalContent=function(){if(modal==='upload-records'){const p=modalData;if(!p.space)Object.assign(p,{space:state.space,query:'',status:'',source:'',selected:[],page:1});const rows=libRecordRows(),pages=Math.max(1,Math.ceil(rows.length/10));p.page=Math.min(p.page,pages);const counts=libCount(state.docs.filter(d=>!d.deleted&&!d.refSourceId&&(p.space==='全部空间'||d.space===p.space)));return modalFrame('上传与解析记录','查看文件进度、失败原因，完成解析后再带入分析。','<div class="lib-record-tabs">'+['全部空间',...SPACE_ORDER].map(s=>B(s,'lib-record-space',p.space===s?'soft sm':'ghost sm','data-space="'+s+'"')).join('')+'</div><div class="lib-record-stats">'+[['解析完成',counts.ready,'green'],['待解析 / 解析中',counts.pending,'amber'],['解析失败',counts.failed,'red']].map(([n,c,t])=>'<div><span>'+n+'</span><b class="'+t+'">'+c+'</b></div>').join('')+'</div><div class="lib-text-toolbar mt"><input id="lib-record-query" aria-label="搜索上传记录" data-lib-input="record-query" placeholder="搜索文件名" value="'+E(p.query)+'"><select aria-label="上传记录状态" data-lib-change="record-status">'+['全部状态','解析完成','未解析','解析中','解析失败'].map(s=>'<option '+((p.status||'全部状态')===s?'selected':'')+'>'+s+'</option>').join('')+'</select><select aria-label="上传记录来源" data-lib-change="record-source"><option value="">全部来源</option><option value="LOCAL" '+(p.source==='LOCAL'?'selected':'')+'>本地上传</option><option value="OSS" '+(p.source==='OSS'?'selected':'')+'>归档同步</option></select>'+B('刷新','lib-record-refresh','sm')+B(p.auto?'停止自动刷新':'自动刷新','lib-record-auto','sm')+B('重新解析（'+p.selected.length+'）','lib-record-retry','sm soft',p.selected.length?'':'disabled')+'</div><div class="mt">'+simpleTable(['选择','文件名称 / 位置','来源','处理进度','更新时间','操作'],pageItems(rows,p.page,10).map(({doc,record})=>['<input type="checkbox" aria-label="选择上传记录 '+E(doc.name)+'" data-lib-change="record-check" data-id="'+doc.id+'" '+(p.selected.includes(doc.id)?'checked':'')+'>','<b class="small">'+E(doc.name)+'</b><div class="hint">'+E(doc.space+' / '+doc.folder)+'</div>',doc.source==='OSS'?'归档同步':'本地上传','<div>'+libStatusTag(doc)+'</div><div class="bar mt"><i style="width:'+(!doc.local&&!doc.importedOnly?100:record?.progress||0)+'%"></i></div>'+(doc.parseError?'<p class="error small">'+E(doc.parseError)+'</p>':''),E(record?.time||doc.uploadedAt?.slice(0,16)||doc.date||'—'),A('打开','source',libAttrs(doc))+(doc.local||doc.parseError?A('继续解析','lib-record-retry-one',libAttrs(doc)):'')]),true)+'</div><div class="lib-pagination"><span>'+rows.length+' 份 · '+p.page+' / '+pages+' 页</span><div class="row">'+B('上一页','lib-record-prev','sm',p.page<=1?'disabled':'')+B('下一页','lib-record-next','sm',p.page>=pages?'disabled':'')+'</div></div>'+(state.libraryAdmin?'<details class="lib-record-admin"><summary>解析服务管理</summary><div class="lib-form-grid mt">'+libForm('本地解析并发','lib-concurrency-local',String(storageQuota.concurrencyLocal||2),'type="number" min="1" max="32"')+libForm('归档解析并发','lib-concurrency-oss',String(storageQuota.concurrencyOss||2),'type="number" min="1" max="32"')+'</div><div class="row mt">'+B('保存并发设置','lib-record-save-concurrency','sm')+B('补全缺失正文','lib-record-fill','sm')+B('清除待解析任务','lib-record-clear','danger sm')+'</div></details>':'')+libErrorHtml,B('关闭','close-modal')+B('上传资料','upload','primary',libWritable()?'':'disabled'),'lib-search-dialog');}
 if(modal==='lib-record-clear')return modalFrame('清除待解析任务','仅处理尚未开始解析的文件，已在解析的任务继续完成。','<p>将清除当前空间中 '+modalData.ids.length+' 个待解析任务。原文件保留，之后可重新解析。</p>',B('取消','close-modal')+B('确认清除','lib-record-confirm-clear','danger'),'small');
 return recordsBase.modalContent();};
handleAction=function(action,el){if(action==='retry-upload'){libReparse([el.dataset.id]);return;}if(action==='upload-records'){openModal('upload-records',{space:state.space,query:'',status:'',source:'',selected:[],page:1});return;}if(!action.startsWith('lib-record-'))return recordsBase.handleAction(action,el);const p=modalData;switch(action){
 case 'lib-record-space':p.space=el.dataset.space;p.page=1;p.selected=[];paintModal();break;
 case 'lib-record-refresh':paintModal();break;
 case 'lib-record-auto':p.auto=!p.auto;if(recordsAutoTimer)clearInterval(recordsAutoTimer);if(p.auto)recordsAutoTimer=setInterval(()=>{if(modal==='upload-records'&&modalData===p&&p.auto)paintModal();else{clearInterval(recordsAutoTimer);recordsAutoTimer=null;}},5000);paintModal();break;
 case 'lib-record-prev':p.page--;paintModal();break;
 case 'lib-record-next':p.page++;paintModal();break;
 case 'lib-record-retry-one':libReparse([el.dataset.id]);break;
 case 'lib-record-retry':{const ids=selectedDocs(p.selected).filter(d=>(d.local||d.parseError)&&libCanParse(d)).map(d=>d.id);if(!ids.length)return libError('请选择未解析或解析失败、且有管理权限的资料。');openModal('lib-reparse',{ids});break;}
 case 'lib-record-save-concurrency':{if(!state.libraryAdmin)return;const a=+$('#lib-concurrency-local').value,b=+$('#lib-concurrency-oss').value;if(![a,b].every(n=>Number.isInteger(n)&&n>=1&&n<=32))return libError('并发数须为1–32的整数。');storageQuota.concurrencyLocal=a;storageQuota.concurrencyOss=b;persist();libDrainParseQueue();toast('并发设置已保存。');break;}
 case 'lib-record-fill':{if(!state.libraryAdmin)return;const ids=libRecordRows().map(r=>r.doc).filter(d=>d.local&&!d.text&&libCanEdit(d)).map(d=>d.id);if(!ids.length)return libError('当前范围没有可补全的正文。');openModal('lib-reparse',{ids});break;}
 case 'lib-record-clear':{if(!state.libraryAdmin)return;const ids=libRecordRows().filter(r=>r.record?.status==='正在上传'||r.record?.status==='未解析').map(r=>r.doc.id);openModal('lib-record-clear',{ids});break;}
 case 'lib-record-confirm-clear':{if(!state.libraryAdmin)return;modalData.ids.forEach(id=>{const r=state.uploads.find(u=>u.id===id);if(r&&r.status!=='正在解析'){r.cancelPending=true;r.status='未解析';r.progress=0;}});libDrainParseQueue();closeModal();render();toast('待解析任务已清除，原文件保留。');break;}
 }};
const libParseQueue=[],libParseActive={LOCAL:0,OSS:0},libParsePromises=new Map();
function libDrainParseQueue(){for(let i=0;i<libParseQueue.length;){const job=libParseQueue[i],pool=job.doc.source==='OSS'?'OSS':'LOCAL',limit=pool==='OSS'?storageQuota.concurrencyOss||2:storageQuota.concurrencyLocal||2;if(job.record.cancelPending){libParseQueue.splice(i,1);job.record.cancelPending=false;libParsePromises.delete(job.doc.id);job.resolve();continue;}if(libParseActive[pool]>=limit){i++;continue;}libParseQueue.splice(i,1);libParseActive[pool]++;recordsBase.parseUploadRecord(job.record,job.doc,job.source).finally(()=>{libParseActive[pool]--;libParsePromises.delete(job.doc.id);job.resolve();libDrainParseQueue();});}}
parseUploadRecord=function(record,doc,source){if(libParsePromises.has(doc.id))return libParsePromises.get(doc.id);const pending=new Promise(resolve=>{record.status='未解析';record.progress=20;libParseQueue.push({record,doc,source,resolve});});libParsePromises.set(doc.id,pending);libDrainParseQueue();return pending;};
const libRecordInput=e=>{const el=e.target;if(el.dataset.libInput!=='record-query')return;e.stopImmediatePropagation();modalData.query=el.value;modalData.page=1;const pos=el.selectionStart;paintModal();$('#lib-record-query')?.focus();$('#lib-record-query')?.setSelectionRange(pos,pos);};
document.addEventListener('input',libRecordInput,true);
document.addEventListener('change',e=>{const el=e.target,k=el.dataset.libChange;if(!['record-status','record-source','record-check'].includes(k))return;e.stopImmediatePropagation();if(k==='record-status')modalData.status=el.value==='全部状态'?'':el.value;else if(k==='record-source')modalData.source=el.value;else modalData.selected=el.checked?[...new Set([...modalData.selected,el.dataset.id])]:modalData.selected.filter(id=>id!==el.dataset.id);modalData.page=1;paintModal();},true);
state.uploads.filter(r=>['正在上传','正在解析'].includes(r.status)).forEach(r=>{const d=file(r.id);if(d?.local){r.status='未解析';r.error='处理未完成，可继续解析。';r.progress=0;}});
render();
const directoryOrderBase=childDirectories;
childDirectories=function(space,path,docs=null){return directoryOrderBase(space,path,docs).sort((a,b)=>(libMeta(space,a).order||0)-(libMeta(space,b).order||0)||a.localeCompare(b,'zh-CN'));};
const folderMoveBase={modalContent,handleAction};
modalContent=function(){if(modal==='lib-move-folder')return modalFrame('移动文件夹',E(modalData.space+' / '+modalData.path),'<label class="field">目标文件夹<select id="lib-folder-target">'+libTargetOptions(modalData.space,modalData.path)+'</select></label><p class="hint mt">保留下级文件、授权与已有分析引用。不能移动到自身或其下级目录。</p>'+libErrorHtml,B('取消','close-modal')+B('确认移动','lib-confirm-folder-move','primary'),'small');return folderMoveBase.modalContent();};
handleAction=function(action,el){if(action==='lib-move-folder'){const c=libFolderContext();if(state.libraryAdmin&&c.path&&libWritable(c.space,c.path)&&!libMeta(c.space,c.path).system)openModal('lib-move-folder',c);return;}
 if(action==='lib-confirm-folder-move'){const {space,path}=modalData,parent=$('#lib-folder-target').value,next=[parent,folderName(path)].filter(Boolean).join('/');if(!state.libraryAdmin||!libWritable(space,path)||!libWritable(space,parent)||libMeta(space,parent).boundOrg)return libError('当前目录不能移动到此位置。');if(underFolder(parent,path))return libError('不能移动到自身或下级文件夹。');if(next===path){closeModal();return;}if(directoryPaths(space).includes(next))return libError('目标位置已有同名文件夹。');libUpdateReferencePaths(space,path,next);state.docs.filter(d=>d.space===space&&underFolder(d.folder,path)).forEach(d=>d.folder=next+folderPath(d.folder).slice(path.length));state.directoryNodes.filter(n=>n.space===space&&underFolder(n.path,path)).forEach(n=>n.path=next+n.path.slice(path.length));Object.entries(folderMeta).filter(([k])=>k.startsWith(space+'::')&&underFolder(k.split('::')[1],path)).forEach(([k,m])=>{folderMeta[directoryKey(space,next+k.split('::')[1].slice(path.length))]=m;delete folderMeta[k];});if(space==='项目空间')state.customFolders=(state.customFolders||[]).map(p=>underFolder(p,path)?next+p.slice(path.length):p);state.directoryNodes.push({space,path:next});state.space=space;state.folder=next;closeModal();render();toast('文件夹已移动，原分析引用保留。');return;}
 if(action==='lib-folder-up'||action==='lib-folder-down'){if(!state.libraryAdmin)return;const {space,path}=modalData,parent=path.split('/').slice(0,-1).join('/'),siblings=childDirectories(space,parent),index=siblings.indexOf(path),target=index+(action==='lib-folder-up'?-1:1);if(target<0||target>=siblings.length)return toast('已位于同级目录'+(target<0?'顶部。':'底部。'));[siblings[index],siblings[target]]=[siblings[target],siblings[index]];siblings.forEach((p,i)=>{(folderMeta[directoryKey(space,p)]??={}).order=i+1;});persist();render();toast('同级顺序已调整。');return;}
 return folderMoveBase.handleAction(action,el);};
function libSetFolderWidth(width){libraryPrefs.folderWidth=Math.min(320,Math.max(135,width));$('.lib-browser')?.style.setProperty('--library-folder-width',libraryPrefs.folderWidth+'px');}
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.lib-folder-resizer');if(!el)return;e.preventDefault();const start=e.clientX,width=$('.lib-folders').getBoundingClientRect().width;el.setPointerCapture(e.pointerId);const move=e=>libSetFolderWidth(width+e.clientX-start),finish=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',finish);persist();};el.addEventListener('pointermove',move);el.addEventListener('pointerup',finish,{once:true});});
document.addEventListener('keydown',e=>{if(!e.target.matches('.lib-folder-resizer')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();libSetFolderWidth((libraryPrefs.folderWidth||202)+(e.key==='ArrowRight'?10:-10));persist();});
render();
// Native Word package: export text as an actual DOCX, without relying on an HTML file extension.
function libWordDownload(name,paragraphs){const cfb=XLSX.CFB.utils.cfb_new();const xml=s=>new TextEncoder().encode(s);XLSX.CFB.utils.cfb_add(cfb,'[Content_Types].xml',xml('<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'));XLSX.CFB.utils.cfb_add(cfb,'_rels/.rels',xml('<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'));XLSX.CFB.utils.cfb_add(cfb,'word/document.xml',xml('<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+paragraphs.flatMap(p=>String(p).split('\n')).map(p=>'<w:p><w:r><w:t xml:space="preserve">'+E(p)+'</w:t></w:r></w:p>').join('')+'<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>'));download(name,new Uint8Array(XLSX.CFB.write(cfb,{fileType:'zip',type:'array'})),'application/vnd.openxmlformats-officedocument.wordprocessingml.document');}
const libExportSearch=libSearchExport;
libSearchExport=function(format){if(format!=='word')return libExportSearch(format);const p=modalData,rows=libSearchRows().filter(r=>p.selected.includes(r.id)),paragraphs=['文本检索结果','检索词：'+p.keyword,'资料范围：'+p.ids.length+' 份；导出 '+rows.length+' 份'];rows.forEach((r,i)=>{const f=file(r.id);paragraphs.push('',(i+1)+'　'+f.name,'资料位置：'+f.space+' / '+f.folder,'匹配内容：'+(r.snippet||f.text||'未读取到正文'));});libWordDownload('文本检索结果.docx',paragraphs);};
// Conventional dropdown behavior: only one open at a time; clicking outside or Escape dismisses it.
document.addEventListener('pointerdown',e=>{$$('.lib-dropdown[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;});},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal)$$('.lib-dropdown[open]').forEach(d=>d.open=false);});
render();
function libPruneDrafts(ids){const removed=new Set(ids);Object.values(state.work).forEach(w=>{if(w.taskId)return;w.ids=(w.ids||[]).filter(id=>!removed.has(id));w.unassigned=(w.unassigned||[]).filter(id=>!removed.has(id));if(removed.has(w.preview))w.preview=w.ids[0];if(removed.has(w.tableA))w.tableA=null;if(removed.has(w.tableB))w.tableB=null;(w.projects||[]).forEach(p=>{p.tender=(p.tender||[]).filter(id=>!removed.has(id));(p.bidders||[]).forEach(b=>b.files=(b.files||[]).filter(id=>!removed.has(id)));});});}
render();

function libUpdateReferencePaths(space,oldPath,newPath){Object.values(folderMeta).forEach(m=>{if(m.reference?.space===space&&underFolder(m.reference.path,oldPath))m.reference.path=newPath+m.reference.path.slice(oldPath.length);});}

function libResponsiveNav(){if(localStorage.getItem('audit-nav-collapsed')===null){const collapsed=innerWidth<=1100;if(navCollapsed!==collapsed){navCollapsed=collapsed;render();}}}
window.addEventListener('resize',libResponsiveNav);libResponsiveNav();
